import csv, io, json, os, sys
from datetime import datetime, timezone, timedelta


def parse_offset(s):
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return timezone(sign * timedelta(hours=int(h), minutes=int(m)))


def parse_time(s, fmt, off):
    if fmt == 'local':
        dt = datetime.strptime(s, '%Y-%m-%d %H:%M:%S').replace(tzinfo=parse_offset(off))
    else:
        if s.endswith('Z') or s.endswith('z'):
            s = s[:-1] + '+00:00'
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def parse_dur(s, fmt):
    if fmt == 'clock':
        t = 0
        for p in s.split(':'):
            t = t * 60 + int(p)
        return t
    return int(float(s))


def read_file(path):
    raw = open(path, 'rb').read().decode('utf-8-sig')
    first = raw.split('\n', 1)[0].rstrip('\r')
    delim = ','
    for d in (',', ';', '\t'):
        if d in first:
            delim = d
            break
    rd = csv.reader(io.StringIO(raw, newline=''), delimiter=delim, quotechar='"')
    rows = []
    header = None
    for r in rd:
        r = [c.strip() for c in r]
        if header is None:
            header = r
            continue
        if not any(r):
            continue
        d = {}
        for i, h in enumerate(header):
            if i < len(r) and r[i] != '':
                d[h] = r[i]
        rows.append(d)
    return rows


def to_int(v):
    return int(float(v)) if not isinstance(v, int) else v


def rnd(x):
    return None if x is None else round(x + 0.0, 2)


def median(v):
    v = sorted(v)
    n = len(v)
    if n % 2:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2


def main(inp, outp):
    cb = json.load(open(os.path.join(inp, 'codebook.json'), encoding='utf-8'))
    wt = json.load(open(os.path.join(inp, 'weighting.json'), encoding='utf-8'))
    plan = json.load(open(os.path.join(inp, 'tables.json'), encoding='utf-8'))
    vkeys = list(cb['versions'].keys())
    qs = cb['questions']
    qmap = {q['id']: q for q in qs}

    exdir = os.path.join(inp, 'exports')
    rows = []
    for fn in sorted(os.listdir(exdir)):
        p = os.path.join(exdir, fn)
        if fn.endswith('.csv') and os.path.isfile(p):
            rows.extend(read_file(p))

    recs = []
    for r in rows:
        v = str(r['form_version'])
        meta = cb['versions'][v]['meta']
        status = r.get(meta['status'])
        complete = status == meta['complete']
        t = parse_time(r[meta['submitted']], meta['submitted_format'], meta.get('utc_offset'))
        dur = parse_dur(r[meta['duration']], meta['duration_format']) if r.get(meta['duration']) is not None else 0
        lp = r.get(meta['last_page'])
        lp = to_int(lp) if lp is not None else 0
        recs.append(dict(v=v, id=r.get(meta['id']), complete=complete, t=t, dur=dur, lp=lp, row=r))

    cnt = {v: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for v in vkeys}
    for x in recs:
        cnt[x['v']]['rows'] += 1
    best = {}
    for x in recs:
        b = best.get(x['id'])
        if b is None or (x['complete'], x['t']) > (b['complete'], b['t']):
            if b is not None:
                cnt[b['v']]['duplicates'] += 1
            best[x['id']] = x
        else:
            cnt[x['v']]['duplicates'] += 1
    kept = []
    mpm = cb['partial_min_page']
    for x in best.values():
        if not x['complete'] and x['lp'] < mpm:
            cnt[x['v']]['short_partials'] += 1
        else:
            kept.append(x)
    meds = {}
    for v in vkeys:
        d = [x['dur'] for x in kept if x['v'] == v and x['complete']]
        meds[v] = median(d) if d else None
    final = []
    for x in kept:
        if x['complete'] and x['dur'] * 5 < meds[x['v']] * 2:
            cnt[x['v']]['speeders'] += 1
        else:
            final.append(x)
    for x in final:
        cnt[x['v']]['complete' if x['complete'] else 'partial'] += 1

    # reading answers
    refyear = int(cb['reference_date'][:4])

    def rec(entry, val):
        m = entry.get('recode')
        if m is not None:
            return to_int(m[val])
        return to_int(val)

    def read(q, entry, row):
        opts = q.get('options', [])
        if q['type'] == 'age':
            val = row.get(entry['column'])
            if val is None:
                return None
            src = entry.get('source')
            if src == 'band':
                return rec(entry, val)
            age = to_int(val)
            if src == 'birth_year':
                age = refyear - age
            for b in q['bands']:
                if b['min'] <= age <= b['max']:
                    return b['code']
            return None
        missing = {o['code'] for o in opts if o.get('missing')}
        excl = {o['code'] for o in opts if o.get('exclusive')}
        if q['type'] == 'single':
            val = row.get(entry['column'])
            if val is None:
                return None
            c = rec(entry, val)
            return None if c in missing else c
        chosen = []
        if 'columns' in entry:
            for code, col in entry['columns'].items():
                if row.get(col) == '1':
                    chosen.append(to_int(code))
        else:
            val = row.get(entry['column'])
            if val is not None:
                for e in val.split(entry['separator']):
                    e = e.strip()
                    if e:
                        chosen.append(rec(entry, e))
        s = set(chosen)
        ne = {c for c in s if c not in excl}
        if ne:
            s = ne
        elif len(s) >= 2:
            s = set()
        s -= missing
        return s if s else None

    n = len(final)
    ans = []
    for x in final:
        a = {}
        for q in qs:
            e = q['versions'].get(x['v'])
            if e is None:
                continue
            if not (x['complete'] or e['page'] <= x['lp']):
                continue
            ai = q.get('ask_if')
            if ai:
                prev = a.get(ai['question'])
                if prev is None:
                    continue
                codes = set(to_int(c) for c in ai['codes'])
                if isinstance(prev, set):
                    if not (prev & codes):
                        continue
                elif prev not in codes:
                    continue
            a[q['id']] = read(q, e, x['row'])
            if a[q['id']] is None:
                a[q['id']] = None
        # asked-but-no-answer marked by presence with None
        ans.append(a)

    # weighting
    w = [1.0] * n
    dims = []
    for d in wt['dimensions']:
        qid = d['question']
        cats = [a.get(qid) for a in ans]
        present = {c for c in cats if c is not None}
        tg = {to_int(k): float(v) for k, v in d['targets'].items() if to_int(k) in present}
        tot = sum(tg.values())
        if not tg or tot <= 0:
            continue
        share = {k: v / tot for k, v in tg.items()}
        idx = {k: [i for i in range(n) if cats[i] == k] for k in share}
        dims.append((share, idx))
    for _ in range(wt.get('max_iterations', 100)):
        ok = True
        for share, idx in dims:
            T = sum(w[i] for l in idx.values() for i in l)
            fs = {}
            for k, l in idx.items():
                W = sum(w[i] for i in l)
                fs[k] = share[k] * T / W if W else 1.0
            for k, l in idx.items():
                for i in l:
                    w[i] *= fs[k]
                if abs(fs[k] - 1) > wt['tolerance']:
                    ok = False
        if ok:
            break
    if n:
        m = sum(w) / n
        hi, lo = wt['cap'] * m, wt['floor'] * m
        w = [min(max(x, lo), hi) for x in w]
        s = sum(w)
        w = [x * n / s for x in w]

    summary = dict(versions=[dict(version=v, **cnt[v]) for v in vkeys], respondents=n)
    if n:
        summary['effective_n'] = rnd(sum(w) ** 2 / sum(x * x for x in w))
        summary['weight_min'] = rnd(min(w))
        summary['weight_max'] = rnd(max(w))
    else:
        summary['effective_n'] = summary['weight_min'] = summary['weight_max'] = None

    # banner
    def codes_of(q):
        if q['type'] == 'age':
            return [b['code'] for b in q['bands']]
        return [o['code'] for o in q['options'] if not o.get('missing')]

    banner = [('total', None, None)]
    for bq in plan['banner']:
        for c in codes_of(qmap[bq]):
            banner.append((f'{bq}:{c}', bq, c))

    def has(v, c):
        return v is not None and (c in v if isinstance(v, set) else v == c)

    tables = []
    for t in plan['tables']:
        q = qmap[t['question']]
        qid = q['id']
        rowcodes = codes_of(q)
        if q['type'] == 'multi':
            rowcodes = [o['code'] for o in q['options'] if not o.get('missing')]
        nets = t.get('nets', [])
        scores = {o['code']: o.get('score') for o in q.get('options', [])}
        cols = []
        for cid, bq, bc in banner:
            mem = [i for i in range(n) if ans[i].get(qid) is not None
                   and (bq is None or ans[i].get(bq) == bc)]
            wb = sum(w[i] for i in mem)
            vals = {}
            keys = [str(c) for c in rowcodes] + [nn['id'] for nn in nets] + (['mean'] if t.get('mean') else [])
            if not mem:
                vals = {k: None for k in keys}
            else:
                for c in rowcodes:
                    vals[str(c)] = rnd(100 * sum(w[i] for i in mem if has(ans[i][qid], c)) / wb)
                for nn in nets:
                    cs = [to_int(c) for c in nn['codes']]
                    vals[nn['id']] = rnd(100 * sum(w[i] for i in mem if any(has(ans[i][qid], c) for c in cs)) / wb)
                if t.get('mean'):
                    vals['mean'] = rnd(sum(w[i] * scores[ans[i][qid]] for i in mem) / wb)
            cols.append(dict(column=cid, base=len(mem), weighted_base=rnd(wb), values=vals))
        tables.append(dict(table=t['id'], columns=cols))

    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(dict(survey=cb['survey'], summary=summary, tables=tables), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
